import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { startLiveBot, endLiveMeeting } from "../services/api";

const LiveMeetingBot = () => {
  const [link, setLink] = useState("");
  const [botJoined, setBotJoined] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const navigate = useNavigate();

  const handleStartBot = async () => {
    if (!link.trim()) {
      setError("Please enter a meeting link");
      return;
    }

    setLoading(true);
    setError(null);
    setSuccess(false);

    try {
      await startLiveBot({ meetingLink: link });
      setBotJoined(true);
      setSuccess(true);
      setLink("");
    } catch (err) {
      setError(err.response?.data?.error || "Failed to start bot");
      console.error("Start bot error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleEndMeeting = async (event) => {
    if (!event.target.files || event.target.files.length === 0) {
      setError("Please select an audio file from the meeting");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append("audio", event.target.files[0]);

      const res = await endLiveMeeting(formData);
      
      if (res.data && res.data.success) {
        navigate("/result", { state: res.data.analysis || res.data });
      } else {
        throw new Error("Failed to process meeting");
      }
    } catch (err) {
      setError(err.response?.data?.error || err.response?.data?.details || "Failed to process meeting");
      console.error("End meeting error:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card">
      <h2>Live Meeting Bot</h2>
      
      {!botJoined ? (
        <>
          <input
            type="text"
            value={link}
            onChange={(e) => setLink(e.target.value)}
            placeholder="Paste Google Meet or Zoom link"
            style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
          />
          {error && <p style={{ color: "red" }}>{error}</p>}
          {success && <p style={{ color: "green" }}>Bot started successfully!</p>}
          <button onClick={handleStartBot} disabled={loading}>
            {loading ? "Starting..." : "Start Meeting Bot"}
          </button>
        </>
      ) : (
        <>
          <p style={{ color: "green" }}>🤖 Bot is in the meeting and recording...</p>
          <p>When the meeting ends, upload the recorded audio file:</p>
          <input
            type="file"
            accept="audio/*"
            onChange={handleEndMeeting}
            style={{ marginTop: "10px" }}
          />
          {error && <p style={{ color: "red" }}>{error}</p>}
          {loading && <p>Processing meeting...</p>}
        </>
      )}
    </div>
  );
};

export default LiveMeetingBot;
